package org.marketreview.nativeapp;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.marketreview.nativeapp.WatchlistWorkspaceModel.need;
import static org.marketreview.nativeapp.WatchlistWorkspaceModel.text;

/** Preserve historical identities and versions; the current config is merged separately. */
final class SectorObservationRestore {
 static final String ARCHIVE="native-manual-leader-observations-archive/v1",PREVIEW="native-manual-leader-observations-preview/v1",RECEIPT="native-manual-leader-observations-receipt/v1";
 static final String SCOPE="全部人工观察历史及原配置版本；只合并新增，同ID保留当前，重复恢复不复活删除项";
 static String hash(Object o)throws Exception{return UnifiedBackup.restoreHash(o);}
 static boolean equal(Object a,Object b)throws Exception{return UnifiedBackup.restoreEqual(a,b);}
 static void keys(JSONObject o,String...names)throws Exception{Set<String> wanted=new HashSet<>(Arrays.asList(names));need(o.length()==wanted.size(),"人工观察原字段缺失或未知");for(Iterator<String> i=o.keys();i.hasNext();)need(wanted.contains(i.next()),"人工观察未知原字段");}
 static void configValid(JSONObject c)throws Exception{SectorLeaderModel.validate(c);keys(c,"schema","revision","updatedAt","sectors");need(c.isNull("updatedAt")||c.opt("updatedAt") instanceof String,"原配置时刻缺失");if(!c.isNull("updatedAt"))RecentRestore.stamp(c.getString("updatedAt"));JSONArray boards=c.getJSONArray("sectors");for(int i=0;i<boards.length();i++){JSONObject b=boards.getJSONObject(i);keys(b,"id","name","description","sortOrder","leaders");JSONArray rows=b.getJSONArray("leaders");for(int j=0;j<rows.length();j++)keys(rows.getJSONObject(j),"id","sectorId","code","name","fullId","identityState","role","reason","weight","note");}UnifiedBackup.sensitive(c,0);}
 static JSONArray versions(JSONArray values)throws Exception{need(values.length()<=30001,"原配置版本太多，未截断");TreeMap<String,JSONObject> unique=new TreeMap<>();for(int i=0;i<values.length();i++){JSONObject c=values.getJSONObject(i);configValid(c);unique.put(hash(c),new JSONObject(c.toString()));}JSONArray out=new JSONArray();for(JSONObject c:unique.values())out.put(c);return out;}
 static void shotValid(JSONObject s)throws Exception{keys(s,"schema","id","sectorId","sectorName","configRevision","capturedAt","manualBoard","rows","summary");SectorLeaderModel.validateShot(s);RecentRestore.stamp(s.getString("capturedAt"));configValid(SectorLeaderModel.empty().put("revision",s.get("configRevision")).put("sectors",new JSONArray().put(s.getJSONObject("manualBoard"))));JSONArray rows=s.getJSONArray("rows");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);keys(r,"id","sectorId","code","name","fullId","identityState","role","reason","weight","note","quote","price","change","amount","strength");JSONObject q=r.getJSONObject("quote");if(q.has("checkedAt")&&!q.isNull("checkedAt")&&!q.optString("checkedAt").isEmpty())RecentRestore.stamp(text(q,"checkedAt"));}UnifiedBackup.sensitive(s,0);}
 static JSONArray rows(JSONArray values)throws Exception{need(values.length()<=2000,"人工观察超过2000条，未截断");TreeMap<String,JSONObject> sorted=new TreeMap<>();for(int i=0;i<values.length();i++){JSONObject s=values.getJSONObject(i);shotValid(s);String id=s.getString("id");need(!sorted.containsKey(id),"原观察ID重复，整批未恢复");sorted.put(id,new JSONObject(s.toString()));}JSONArray out=new JSONArray();for(JSONObject s:sorted.values())out.put(s);return out;}
 static JSONObject payload(JSONObject input)throws Exception{keys(input,"schema","config","configVersions","observations");need(ARCHIVE.equals(input.optString("schema")),"人工观察完整档案无效");JSONObject c=input.getJSONObject("config");configValid(c);JSONArray all=versions(input.getJSONArray("configVersions"));boolean found=false;for(int i=0;i<all.length();i++)found|=equal(all.get(i),c);need(found,"档案缺完整原当前配置版本");JSONObject out=new JSONObject().put("schema",ARCHIVE).put("config",new JSONObject(c.toString())).put("configVersions",all).put("observations",rows(input.getJSONArray("observations")));need(out.toString().getBytes(StandardCharsets.UTF_8).length<=8*1024*1024,"完整人工观察域超过8MiB，未截断");return out;}
 static JSONObject packet(JSONObject c,JSONArray shots,JSONArray all)throws Exception{JSONArray copied=new JSONArray(all.toString()).put(c);return payload(new JSONObject().put("schema",ARCHIVE).put("config",c).put("configVersions",versions(copied)).put("observations",shots));}
 static void summaryValid(JSONObject s)throws Exception{RecentRestore.summary(s);}
 static JSONObject snapshot(JSONObject c,JSONArray shots,JSONArray all,JSONObject imports,JSONObject receipts,boolean hasTable)throws Exception{summaryValid(imports);summaryValid(receipts);JSONObject p=packet(c,shots,all),m=new JSONObject().put("schema","native-manual-observations-state/v1").put("payloadHash",hash(p)).put("legacyImports",imports).put("restoreReceipts",receipts).put("hasReceiptsTable",hasTable);return new JSONObject().put("payload",p).put("restoreState",m).put("baseline",hash(m));}
 static void snapshotValid(JSONObject s)throws Exception{keys(s,"payload","restoreState","baseline");JSONObject p=payload(s.getJSONObject("payload")),m=s.getJSONObject("restoreState");keys(m,"schema","payloadHash","legacyImports","restoreReceipts","hasReceiptsTable");need("native-manual-observations-state/v1".equals(m.optString("schema"))&&m.opt("hasReceiptsTable") instanceof Boolean,"人工观察完整基线缺失");summaryValid(m.getJSONObject("legacyImports"));summaryValid(m.getJSONObject("restoreReceipts"));need(m.getString("payloadHash").equals(hash(p))&&s.getString("baseline").equals(hash(m)),"人工观察基线校验失败");}
 static void ids(JSONArray values,Set<String> seen)throws Exception{for(int i=0;i<values.length();i++){Object v=values.get(i);need(v instanceof String&&!((String)v).trim().isEmpty()&&((String)v).length()<=128&&seen.add((String)v),"原观察回执ID无效或重复");}need(seen.size()<=2000,"回执观察ID超限");}
 static void receiptValid(JSONObject r)throws Exception{keys(r,"schema","sourceKey","committedAt","beforeBaseline","expectedRowsHash","legacyImports","insertedIds","equalIds","conflictIds","configVersions","committedConfig","atomicWithinStore","sha256");UnifiedBackup.sealed(r);need(RECEIPT.equals(r.optString("schema"))&&Boolean.TRUE.equals(r.opt("atomicWithinStore")),"人工观察回执无效");for(String k:new String[]{"sourceKey","beforeBaseline","expectedRowsHash"})RecentRestore.digest(r.getString(k));RecentRestore.stamp(r.getString("committedAt"));summaryValid(r.getJSONObject("legacyImports"));Set<String> seen=new HashSet<>();for(String k:new String[]{"insertedIds","equalIds","conflictIds"})ids(r.getJSONArray(k),seen);need(equal(versions(r.getJSONArray("configVersions")),r.getJSONArray("configVersions")),"回执完整原版本无效");configValid(r.getJSONObject("committedConfig"));need(r.toString().getBytes(StandardCharsets.UTF_8).length<=16*1024*1024,"人工观察单回执超过16MiB，未截断");}
 static JSONObject preview(JSONObject input,JSONObject before,JSONObject previous)throws Exception{
  snapshotValid(before);JSONObject incoming=payload(input),current=before.getJSONObject("payload"),meta=before.getJSONObject("restoreState");String key=hash(incoming);if(previous!=null){receiptValid(previous);need(key.equals(previous.getString("sourceKey")),"旧回执不属于该原观察档案");}
  TreeMap<String,JSONObject> existing=new TreeMap<>(),target=new TreeMap<>();JSONArray old=current.getJSONArray("observations");for(int i=0;i<old.length();i++){JSONObject s=old.getJSONObject(i);existing.put(s.getString("id"),s);}target.putAll(existing);JSONArray actions=new JSONArray(),source=incoming.getJSONArray("observations");
  for(int i=0;i<source.length();i++){JSONObject s=source.getJSONObject(i);String id=s.getString("id"),status;if(previous!=null)status="duplicate-import";else if(!existing.containsKey(id)){target.put(id,s);status="insert";}else status=equal(existing.get(id),s)?"equal":"conflict";actions.put(new JSONObject().put("id",id).put("status",status));}
  JSONArray result=new JSONArray();for(JSONObject s:target.values())result.put(s);rows(result);JSONObject cp=previous==null?SectorLeaderModel.preview(incoming.getJSONObject("config").toString().getBytes(StandardCharsets.UTF_8),current.getJSONObject("config")):new JSONObject().put("config",current.getJSONObject("config")).put("addedBoards",0).put("addedLeaders",0).put("unresolvedCount",0).put("conflicts",new JSONArray());boolean changed=!equal(cp.getJSONObject("config").getJSONArray("sectors"),current.getJSONObject("config").getJSONArray("sectors"));if(previous==null)need(meta.getJSONObject("restoreReceipts").getLong("count")<10000,"恢复回执达到10000次，未写入");
  return UnifiedBackup.seal(new JSONObject().put("schema",PREVIEW).put("sourceKey",key).put("incoming",incoming).put("expected",before.get("baseline")).put("before",current).put("legacyImports",meta.get("legacyImports")).put("restoreReceipts",meta.get("restoreReceipts")).put("actions",actions).put("targetObservations",result).put("expectedRowsHash",hash(result)).put("configPreview",cp).put("configChanged",changed).put("previousReceipt",previous==null?JSONObject.NULL:previous).put("noChange",previous!=null));
 }
 static void previewValid(JSONObject p)throws Exception{keys(p,"schema","sourceKey","incoming","expected","before","legacyImports","restoreReceipts","actions","targetObservations","expectedRowsHash","configPreview","configChanged","previousReceipt","noChange","sha256");UnifiedBackup.sealed(p);need(PREVIEW.equals(p.optString("schema"))&&p.opt("configChanged") instanceof Boolean&&p.opt("noChange") instanceof Boolean,"人工观察确认预览无效");JSONObject source=payload(p.getJSONObject("incoming"));payload(p.getJSONObject("before"));need(p.getString("sourceKey").equals(hash(source))&&p.getString("expectedRowsHash").equals(hash(rows(p.getJSONArray("targetObservations")))),"人工观察预览摘要不符");RecentRestore.digest(p.getString("expected"));summaryValid(p.getJSONObject("legacyImports"));summaryValid(p.getJSONObject("restoreReceipts"));configValid(p.getJSONObject("configPreview").getJSONObject("config"));if(!p.isNull("previousReceipt"))receiptValid(p.getJSONObject("previousReceipt"));}
 static JSONObject receipt(JSONObject p,JSONObject committed,String at)throws Exception{previewValid(p);need(!p.getBoolean("noChange"),"重复恢复只重读原回执");RecentRestore.stamp(at);configValid(committed);JSONObject before=p.getJSONObject("before").getJSONObject("config");need(committed.getLong("revision")==before.getLong("revision")+(p.getBoolean("configChanged")?1:0)&&equal(committed.getJSONArray("sectors"),p.getJSONObject("configPreview").getJSONObject("config").getJSONArray("sectors")),"配置合并原生提交版本/字段不符");JSONArray added=new JSONArray(),same=new JSONArray(),conflict=new JSONArray(),actions=p.getJSONArray("actions");for(int i=0;i<actions.length();i++){JSONObject a=actions.getJSONObject(i);String status=a.getString("status");if(status.equals("insert"))added.put(a.get("id"));else if(status.equals("equal"))same.put(a.get("id"));else if(status.equals("conflict"))conflict.put(a.get("id"));else need(false,"观察预览动作无效");}JSONArray all=new JSONArray(p.getJSONObject("before").getJSONArray("configVersions").toString()),incoming=p.getJSONObject("incoming").getJSONArray("configVersions");for(int i=0;i<incoming.length();i++)all.put(incoming.get(i));all.put(before).put(committed);JSONObject r=UnifiedBackup.seal(new JSONObject().put("schema",RECEIPT).put("sourceKey",p.get("sourceKey")).put("committedAt",at).put("beforeBaseline",p.get("expected")).put("expectedRowsHash",p.get("expectedRowsHash")).put("legacyImports",p.get("legacyImports")).put("insertedIds",added).put("equalIds",same).put("conflictIds",conflict).put("configVersions",versions(all)).put("committedConfig",committed).put("atomicWithinStore",true));receiptValid(r);return r;}
 static boolean matches(JSONObject p,JSONObject after)throws Exception{previewValid(p);snapshotValid(after);JSONObject a=after.getJSONObject("payload"),m=after.getJSONObject("restoreState"),before=p.getJSONObject("before").getJSONObject("config");return hash(a.getJSONArray("observations")).equals(p.getString("expectedRowsHash"))&&equal(m.get("legacyImports"),p.get("legacyImports"))&&m.getJSONObject("restoreReceipts").getLong("count")==p.getJSONObject("restoreReceipts").getLong("count")+(p.getBoolean("noChange")?0:1)&&equal(a.getJSONObject("config").getJSONArray("sectors"),p.getJSONObject("configPreview").getJSONObject("config").getJSONArray("sectors"))&&a.getJSONObject("config").getLong("revision")==before.getLong("revision")+(p.getBoolean("configChanged")?1:0);}
 static boolean verify(JSONObject p,JSONObject r,JSONObject after,JSONObject saved)throws Exception{receiptValid(r);receiptValid(saved);if(!matches(p,after)||!equal(r,saved)||!r.getString("sourceKey").equals(p.getString("sourceKey")))return false;if(p.getBoolean("noChange"))return equal(r,p.getJSONObject("previousReceipt"))&&after.getString("baseline").equals(p.getString("expected"));return equal(after.getJSONObject("payload").getJSONObject("config"),r.getJSONObject("committedConfig"))&&equal(after.getJSONObject("payload").getJSONArray("configVersions"),r.getJSONArray("configVersions"));}
 static String describeShot(JSONObject s)throws Exception{shotValid(s);return "原观察ID："+s.getString("id")+"\n原板块ID / 名称："+s.getString("sectorId")+" / "+s.getString("sectorName")+"\n原配置版本："+s.getLong("configRevision")+"\n原冻结时刻："+s.getString("capturedAt")+"\n完整留存原字段（未知数保留null）：\n"+s.toString(2)+"\n";}
 static String status(String s){switch(s){case "insert":return "新增原ID";case "equal":return "相同完整原字段，保留当前";case "conflict":return "同ID冲突，保留当前";default:return "重复档案，保留原回执";}}
 static String describeOperationRow(JSONObject row)throws Exception{if(!"manual-leader-observations".equals(row.optString("id"))||row.optJSONObject("preview")==null||!PREVIEW.equals(row.getJSONObject("preview").optString("schema")))return "";JSONObject p=row.getJSONObject("preview");StringBuilder out=new StringBuilder("\n人工观察恢复保留原版本、原ID与来源；历史字段不按当前名单改写。\n");if(p.getBoolean("noChange"))out.append("该档案已有原回执；不会复活用户其后删除的记录或配置成员。\n");JSONArray all=p.getJSONObject("incoming").getJSONArray("configVersions");for(int i=0;i<all.length();i++){JSONObject c=all.getJSONObject(i);out.append("原完整配置版本：").append(c.getLong("revision")).append(" · 内容摘要 ").append(hash(c)).append('\n').append(c.toString(2)).append('\n');}Map<String,JSONObject> current=new HashMap<>();JSONArray old=p.getJSONObject("before").getJSONArray("observations"),actions=p.getJSONArray("actions");for(int i=0;i<old.length();i++){JSONObject s=old.getJSONObject(i);current.put(s.getString("id"),s);}Map<String,String> states=new HashMap<>();for(int i=0;i<actions.length();i++){JSONObject a=actions.getJSONObject(i);states.put(a.getString("id"),a.getString("status"));}JSONArray shots=p.getJSONObject("incoming").getJSONArray("observations");for(int i=0;i<shots.length();i++){JSONObject s=shots.getJSONObject(i);String id=s.getString("id");out.append("\n原观察处理：").append(status(states.get(id))).append('\n').append(describeShot(s));if(current.containsKey(id))out.append("当前完整保留项：\n").append(describeShot(current.get(id)));}JSONObject r=row.optJSONObject("receipt");if(r==null)r=p.optJSONObject("previousReceipt");if(r!=null)out.append("完整原恢复回执：\n").append(r.toString(2)).append('\n');return out.toString();}
}
